import sys
import heapq

def main():
    import sys
    import heapq

    def readints():
        return list(map(int, sys.stdin.readline().split()))

    n, m, s = readints()
    bugs = readints()
    students = readints()
    costs = readints()

    # Sort bugs and students
    bugs.sort()
    students.sort()

    # Priority queue to store (days, passes, student_index)
    pq = []
    for i in range(n):
        if students[i] >= bugs[0]:
            heapq.heappush(pq, (1, costs[i], i))

    if not pq:
        print("NO")
        return

    bug_index = 0
    result = [-1] * m

    while pq:
        days, passes, student_index = heapq.heappop(pq)

        if passes > s:
            continue

        # Assign this student to the current bug
        result[bug_index] = student_index + 1
        bug_index += 1

        if bug_index == m:
            break

        # Push the next bug for this student if possible
        if students[student_index] >= bugs[bug_index]:
            heapq.heappush(pq, (days + 1, passes + costs[student_index], student_index))

    if bug_index < m:
        print("NO")
    else:
        print("YES")
        print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
